/* legacy fixed-width record -> canonical order */
static int legacy_to_canonical(const char *rec, size_t len, struct order *out) {
    if (len != LEGACY_REC_LEN) return -1;              /* validate before mapping */
    out->id  = (uint32_t)strtoul(field(rec, 0, 10), NULL, 10);
    out->qty = (uint16_t)atoi(field(rec, 10, 4));
    return copy_span(field(rec, 14, 8), out->sku, sizeof out->sku);  /* bounded, NUL-safe */
}
